import { useState, useEffect } from 'react';

const cache = new Map<string, { data: any; timestamp: number }>();
const CACHE_TTL = 5 * 60 * 1000;
const MUTATING_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
let cacheVersion = 0;
const listeners = new Set<() => void>();

export function invalidateCache(prefix: string) {
  for (const key of cache.keys()) if (key.startsWith(prefix)) cache.delete(key);
  cacheVersion++;
  listeners.forEach(l => l());
}

export async function fetchFinanceData<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const method = (options?.method ?? 'GET').toUpperCase();
  const isMutation = MUTATING_METHODS.has(method);
  if (!isMutation) {
    const cached = cache.get(endpoint);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) return cached.data as T;
  }
  const response = await fetch(endpoint, options);
  if (!response.ok) throw new Error(`Failed to fetch ${endpoint}`);
  const data = await response.json();
  if (!isMutation) cache.set(endpoint, { data, timestamp: Date.now() });
  cacheVersion++;
  listeners.forEach(l => l());
  return data;
}

export function subscribe(fn: () => void) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

export function getVersion() {
  return cacheVersion;
}

export function useFinanceData<T>(endpoint: string): { data: T | null; isLoading: boolean; error: Error | null; refetch: () => Promise<void> } {
  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const result = await fetchFinanceData<T>(endpoint);
        setData(result);
      } catch (err) {
        setError(err as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [endpoint]);

  useEffect(() => {
    const unsubscribe = subscribe(() => {
      fetchData();
    });

    return () => unsubscribe();
  }, [endpoint]);

  const refetch = async () => {
    setIsLoading(true);
    setData(null);
    setError(null);
    await fetchData();
  };

  return { data, isLoading, error, refetch };
}

export async function useSubmit(endpoint: string, options?: RequestInit) {
  const response = await fetchFinanceData(endpoint, options);
  invalidateCache(endpoint);
  return response;
}
